## CODE FOR GETTING BASIC OASIS DEMOGRAPHIC DATA ### Sophia H. Lipetzky# Last edited 08/31/2026import osimport pandas as pd# Set directory with all PT files downloaded from OneDrivein_dir = '/Users/sophialipetzky/Documents/THL/oasis_data'# Iteratively load in all participants enrollment data and concatonate into one large data framedf_raw = pd.DataFrame()for root, dirs, files in os.walk(in_dir):    for file in files:         if file.endswith('nrollment.csv'):           raw_data = pd.read_csv(os.path.join(root, file))           df_temp = pd.DataFrame(raw_data)           print(file)           print(df_temp.shape)           df_raw = pd.concat([df_raw, df_temp], ignore_index = True, join = 'outer')          # Create a dataframe of desired variables (ie. birth control data; demo_horm_current = 1 -> on BC)df_mc_data = df_raw[['record_id', 'demo_horm_current', 'demo_horm_bc']]# Download your desired dataframe as a .csvdf_mc_data.to_csv(in_dir+'../birthcontrol_data.csv', index = False)    